import{_ as r,o as t,c as a,a2 as n}from"./chunks/framework.XWkMPaqj.js";const f=JSON.parse('{"title":"论文成果","description":"","frontmatter":{"title":"论文成果","order":17},"headers":[],"relativePath":"publications/papers.md","filePath":"publications/papers.md"}'),o={name:"publications/papers.md"};function i(l,e,s,g,c,p){return t(),a("div",null,[...e[0]||(e[0]=[n('<h1 id="论文成果" tabindex="-1">论文成果 <a class="header-anchor" href="#论文成果" aria-label="Permalink to &quot;论文成果&quot;">​</a></h1><h2 id="msa" tabindex="-1">MSA <a class="header-anchor" href="#msa" aria-label="Permalink to &quot;MSA&quot;">​</a></h2><ol><li><p><a href="https://doi.org/10.1093/molbev/msac166" target="_blank" rel="noreferrer"><strong>HAlign 3</strong></a>: fast multiple alignment of ultra-large numbers of similar DNA/RNA sequences. <strong>Molecular Biology and Evolution</strong>. 2022 (<a href="https://github.com/malabz/HAlign-3" target="_blank" rel="noreferrer">soft</a>)</p></li><li><p><a href="https://academic.oup.com/bioinformatics/article/40/12/btae718/7912339" target="_blank" rel="noreferrer"><strong>HAlign 4</strong></a>: a new strategy for rapidly aligning millions of sequences. <strong>Bioinformatics</strong>. 2024 (<a href="https://github.com/malabz/HAlign-4" target="_blank" rel="noreferrer">soft</a>)</p></li></ol><p>数据集推荐:适合处理序列数量极多、长度中等、整体相似度较高的数据集。</p><ol start="3"><li><a href="https://doi.org/10.1093/bioinformatics/btae014" target="_blank" rel="noreferrer"><strong>FMAlign2</strong></a>: a novel fast multiple nucleotide sequence alignment method for ultralong datasets. <strong>Bioinformatics</strong>. 2024 (<a href="https://github.com/malabz/FMAlign2" target="_blank" rel="noreferrer">soft</a>)</li></ol><p>数据集推荐:适合序列数量少，但单条序列长度很长，且整体相似度较高的数据集。</p><ol start="4"><li><a href="https://genome.cshlp.org/content/early/2026/07/23/gr282046126" target="_blank" rel="noreferrer"><strong>minipoa</strong></a>: Fast and memory efficient partial order alignment with minipoa. <strong>Genome Research</strong>. 2026 (<a href="https://github.com/NCl3-lhd/minipoa" target="_blank" rel="noreferrer">soft</a>)</li></ol><p>数据集推荐:适合序列数量中等，序列长度长，且整体相似度在中等以上的数据集。</p><h2 id="msa-post-processing" tabindex="-1">MSA post-processing <a class="header-anchor" href="#msa-post-processing" aria-label="Permalink to &quot;MSA post-processing&quot;">​</a></h2><ol><li><p><a href="https://doi.org/10.1371/journal.pcbi.1011988" target="_blank" rel="noreferrer"><strong>TPMA</strong></a>: A two pointers meta-alignment tool to ensemble different multiple nucleic acid sequence alignments. <strong>PLOS COMPUTATIONAL BIOLOGY</strong>. 2024 (<a href="https://github.com/malabz/TPMA" target="_blank" rel="noreferrer">soft</a>)</p></li><li><p><a href="https://academic.oup.com/nargab/article/6/4/lqae170/7928182" target="_blank" rel="noreferrer"><strong>ReAlign-N</strong></a>: an integrated realignment approach for multiple nucleic acid sequence alignment, combining global and local realignments. <strong>NAR Genomics and Bioinformatics</strong>. 2024 (<a href="https://github.com/malabz/ReAlign-N" target="_blank" rel="noreferrer">soft</a>)</p></li><li><p><a href="https://link.springer.com/chapter/10.1007/978-981-95-0030-7_38" target="_blank" rel="noreferrer"><strong>ReAlign-Star</strong></a>: an optimized realignment method for multiple sequence alignment, targeting star algorithm tools. <strong>International Conference on Intelligent Computing</strong>. 2025 (<a href="https://github.com/malabz/ReAlign-Star" target="_blank" rel="noreferrer">soft</a>)</p></li><li><p><a href="https://academic.oup.com/bioinformatics/article/41/8/btaf421/8213638?login=false" target="_blank" rel="noreferrer"><strong>ReAlign-P</strong></a>: a vertical iterative realignment method for protein multiple sequence alignment. <strong>Bioinformatics</strong>. 2025 (<a href="https://github.com/malabz/ReAlign-P" target="_blank" rel="noreferrer">soft</a>)</p></li></ol><h2 id="mga" tabindex="-1">MGA <a class="header-anchor" href="#mga" aria-label="Permalink to &quot;MGA&quot;">​</a></h2><ol><li><p><a href="https://doi.org/10.1101/gr.279763.124" target="_blank" rel="noreferrer">Fast sequence alignment for centromere with RaMA</a>. <strong>Genome Research</strong>. 2025 (<a href="https://github.com/metaphysicser/RaMA" target="_blank" rel="noreferrer">soft</a>)</p></li><li><p><a href="https://link.springer.com/article/10.1186/s13059-025-03881-3" target="_blank" rel="noreferrer"><strong>HAlign-G</strong></a> : rapid and low-memory multiple-genome aligner for large-scale closely related genomes. <strong>Genome Biology</strong>. 2025 (<a href="https://github.com/malabz/HAlign-G" target="_blank" rel="noreferrer">soft</a>)</p></li></ol><h2 id="psa" tabindex="-1">PSA <a class="header-anchor" href="#psa" aria-label="Permalink to &quot;PSA&quot;">​</a></h2><ol><li><a href="https://doi.org/10.1093/bib/bbaf061" target="_blank" rel="noreferrer"><strong>FORAlign</strong></a>: Accelerating gap-affine DNA pairwise sequence alignment using FOR-blocks based on FOur Russians approach with linear space complexity. <strong>Briefings in Bioinformatics</strong>. 2025 (<a href="https://github.com/malabz/FORAlign" target="_blank" rel="noreferrer">soft</a>)</li></ol><h2 id="review" tabindex="-1">Review <a class="header-anchor" href="#review" aria-label="Permalink to &quot;Review&quot;">​</a></h2><ol><li><p><a href="https://www.mdpi.com/2218-273X/12/4/546" target="_blank" rel="noreferrer">Developments in Algorithms for Sequence Alignment</a>: A Review. <strong>Biomolecules</strong>. 2022</p></li><li><p><a href="https://doi.org/10.1093/bib/bbac069" target="_blank" rel="noreferrer">A survey on the algorithm and development of multiple sequence alignment</a>. <strong>Briefings in Bioinformatics</strong>. 2022</p></li><li><p><a href="https://www.frontiersin.org/journals/genetics/articles/10.3389/fgene.2025.1722317/full" target="_blank" rel="noreferrer">Advances in post-processing methods for multiple sequence alignment.</a> <strong>Frontiers in Genetics</strong>. 2025</p></li></ol><h2 id="其他论文" tabindex="-1">其他论文 <a class="header-anchor" href="#其他论文" aria-label="Permalink to &quot;其他论文&quot;">​</a></h2><ol><li><p><a href="https://academic.oup.com/bioinformatics/article/31/15/2475/188425" target="_blank" rel="noreferrer"><strong>HAlign</strong></a>: Fast multiple similar DNA/RNA sequence alignment based on the centre star strategy. <strong>Bioinformatics</strong>. 2015 (<a href="https://github.com/malabz/HAlign" target="_blank" rel="noreferrer">soft</a>)</p></li><li><p><a href="https://link.springer.com/content/pdf/10.1186/s13015-017-0116-x.pdf" target="_blank" rel="noreferrer"><strong>HAlign 2</strong></a>: efficient ultra-large multiple sequence alignment and phylogenetic tree reconstruction with distributed and parallel computing. <strong>Algorithms for Molecular Biology</strong>. 2017 (<a href="https://github.com/malabz/HAlign" target="_blank" rel="noreferrer">soft</a>)</p></li><li><p><a href="https://academic.oup.com/bib/article/23/1/bbab519/6458932" target="_blank" rel="noreferrer"><strong>FMAlign</strong></a>: A novel fast multiple nucleotide sequence alignment method based on FM-index. <strong>Briefings in Bioinformatics</strong>. 2021</p></li><li><p><a href="https://pubmed.ncbi.nlm.nih.gov/28646874/" target="_blank" rel="noreferrer"><strong>CMSA</strong></a>: a heterogeneous CPU/GPU computing system for multiple similar RNA/DNA sequence alignment. <strong>BMC Bioinformatics</strong>. 2017 (<a href="https://github.com/wangvsa/CMSA" target="_blank" rel="noreferrer">soft</a>)</p></li><li><p><a href="https://link.springer.com/article/10.1186/s12918-017-0476-3" target="_blank" rel="noreferrer">Reconstructing evolutionary trees in parallel for massive sequences</a>. <strong>BMC Systems Biology</strong>. 2017</p></li><li><p><a href="https://www.liebertpub.com/doi/10.1089/cmb.2017.0040" target="_blank" rel="noreferrer">Multiple Sequence Alignment Based on a Suffix Tree and Center-Star Strategy</a>: A Linear Method for Multiple Nucleotide Sequence Alignment on Spark Parallel Framework. <strong>Journal of Computational Biology</strong>. 2017 (<a href="https://github.com/suwenhecn/MASC" target="_blank" rel="noreferrer">soft</a>)</p></li><li><p><a href="http://www.jgenetgenomics.org/en/article/doi/10.1016/j.jgg.2018.07.004" target="_blank" rel="noreferrer"><strong>VCSRA</strong></a>: A fast and accurate multiple sequence alignment algorithm with a high degree of parallelism. <strong>Journal of Genetics and Genomics</strong>. 2018 (<a href="https://github.com/DongDongNeophyte/VCSRA_code" target="_blank" rel="noreferrer">soft</a>)</p></li><li><p><a href="http://www.juestc.uestc.edu.cn/cn/article/doi/10.12178/1001-0548.2021406" target="_blank" rel="noreferrer">Improved Center Star Alignment Algorithm Based on Profile Alignment</a>. <strong>Journal of University of Electronic Science and Technology of China</strong>. 2022</p></li><li><p><a href="https://doi.org/10.1093/bioinformatics/btac658" target="_blank" rel="noreferrer"><strong>WMSA</strong></a>: a novel method for multiple sequence alignment of DNA sequences. <strong>Bioinformatics</strong>. 2022 (<a href="https://github.com/malabz/WMSA/" target="_blank" rel="noreferrer">soft</a>)</p></li><li><p><a href="https://doi.org/10.1093/bib/bbad190" target="_blank" rel="noreferrer"><strong>WMSA2</strong></a>: a multiple DNA/RNA sequence alignment tool implemented with accurate progressive mode and a fast win-win mode combining the center star and progressive strategies. <strong>Briefings in Bioinformatics</strong>. 2023 (<a href="https://github.com/malabz/WMSA2/" target="_blank" rel="noreferrer">soft</a>)</p></li><li><p><a href="https://doi.org/10.1093/gigascience/giaf163" target="_blank" rel="noreferrer"><strong>deMEM</strong></a>: a novel divide-and-conquer framework based on de Bruijn graph for scalable multiple sequence alignment. <strong>GigaScience</strong>. 2026 (<a href="https://github.com/malabz/deMEM" target="_blank" rel="noreferrer">soft</a>)</p></li></ol>',18)])])}const h=r(o,[["render",i]]);export{f as __pageData,h as default};
